window.kbPageData["views/entry/k-731b7d1ed8ef31b2"] = {"key":"entry/k-731b7d1ed8ef31b2","state":{"route":"entry/k-731b7d1ed8ef31b2"},"node":{"id":"k-731b7d1ed8ef31b2","mode":"k","title":"湿地碳释放与氨挥发","type":"原理与机制","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["湿地碳释放的主要气体及其形成机制"],"qs":["江苏 2024 A类 行测#10"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"湿地中的有机碳可经生物呼吸和微生物分解，以二氧化碳、甲烷等形式释放。积水造成的缺氧环境有利于微生物产甲烷，氨挥发则是独立的氮释放过程。","review":{"definition":"湿地中的有机碳可经生物呼吸和微生物分解，以二氧化碳、甲烷等形式释放。积水造成的缺氧环境有利于微生物产甲烷，氨挥发则是独立的氮释放过程。","explanation":"施用氮肥的淹水稻田可观测到氨挥发。水体铵浓度和pH较高时，氨挥发更值得关注。天然潮汐盐沼的实测研究也将退潮后裸露地表的排放识别为当地氨浓度的可能来源。本题是选非题，参考答案选C，但C项表述为湿地“会排放出甲烷、氨气”，并未将氨列为碳释放产物。题目未限定湿地类型和条件，单凭碳释放主要涉及二氧化碳和甲烷，无法判定C项错误。","references":[{"source":"web-651dc7ccb5eb5e72","location":"田间试验结果，IRRI试验田氮肥段","quote":"The NH₃ volatilization losses were highest when all the N was broadcast into the water"},{"source":"web-63ad01b12a6b46de","location":"讨论与结论，退潮时的局地氨来源","quote":"fluxes from the land surface exposed as the tide recedes"}],"evidence":"碳释放以二氧化碳和甲烷为主。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 A类 行测#10":{"paper":"江苏 2024 A类 行测","n":10,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",4],"card":"0d0b36fb4c369dfdebd9403c","links":[{"id":"k-731b7d1ed8ef31b2","role":"直接考查","why":"湿地中固定的碳可经呼吸作用或微生物分解释放，二氧化碳和甲烷是主要的碳释放气体。"}]}},"terms":{},"references":{"web-651dc7ccb5eb5e72":{"name":"Ammonia Volatilization Losses from Flooded Rice Soils","url":"https://agronomy-rice.ucdavis.edu/sites/g/files/dgvnsk11966/files/media/documents/_AMMONIA%20VOLATILIZATION%20LOSSES%20FROM%20FLOODED%20RICE%20SOILS_0.pdf"},"web-63ad01b12a6b46de":{"name":"Atmospheric Ammonia Measurements Over a Coastal Salt Marsh Ecosystem Along the Mid‐Atlantic U.S.","url":"https://repository.library.noaa.gov/view/noaa/53834/noaa_53834_DS1.pdf"}},"topics":[],"units":{"k-731b7d1ed8ef31b2":[["江苏 2024 A类 行测#10"]]}};
